from collections.abc import Callable

import pytest


def wrapped(job: Callable[[], str]) -> str:
    """Run job once and return "start:" + job's result + ":end".

    The helper uses no capabilities of its own: it does no I/O, prints
    nothing, and logs nothing. Any exception raised by job propagates
    unchanged.
    """
    return "start:" + job() + ":end"


def test_wrapped_basic() -> None:
    assert wrapped(lambda: "x") == "start:x:end"


def test_wrapped_empty_result() -> None:
    assert wrapped(lambda: "") == "start::end"


def test_wrapped_result_with_special_chars() -> None:
    assert wrapped(lambda: "a:b\nc") == "start:a:b\nc:end"


def test_wrapped_calls_job_exactly_once() -> None:
    calls: list[int] = []

    def job() -> str:
        calls.append(1)
        return "r"

    assert wrapped(job) == "start:r:end"
    assert len(calls) == 1


def test_wrapped_propagates_exception() -> None:
    class Boom(Exception):
        pass

    def job() -> str:
        raise Boom("bad")

    with pytest.raises(Boom):
        wrapped(job)


def test_wrapped_job_uses_caller_state() -> None:
    state = {"n": 0}

    def job() -> str:
        state["n"] += 1
        return str(state["n"])

    assert wrapped(job) == "start:1:end"
    assert wrapped(job) == "start:2:end"


def test_wrapped_prints_nothing(capsys: pytest.CaptureFixture[str]) -> None:
    wrapped(lambda: "quiet")
    captured = capsys.readouterr()
    assert captured.out == ""
    assert captured.err == ""


def test_wrapped_only_job_output_is_printed(
    capsys: pytest.CaptureFixture[str],
) -> None:
    def job() -> str:
        print("from job")
        return "v"

    assert wrapped(job) == "start:v:end"
    captured = capsys.readouterr()
    assert captured.out == "from job\n"
    assert captured.err == ""


def test_wrapped_logs_nothing(caplog: pytest.LogCaptureFixture) -> None:
    with caplog.at_level(0):
        wrapped(lambda: "quiet")
    assert caplog.records == []
